// 1. Get the data passed from the "Find Slots" node
const data = $input.first().json;
const potentialSlots = data.potentialSlots;
const events = data.events || [];

// 2. Get the timezone and Vapi tool call ID
const timeZone = $('Edit Fields').first().json.timeZone || 'America/Chicago';
const toolCallId = $('Webhook').first().json.body.message.toolCalls[0].id;

// 3. Filter the slots based on the Max 2 Barbers rule
let availableSlots = [];

potentialSlots.forEach(slot => {
    const slotStart = new Date(slot.start);
    const slotEnd = new Date(slot.end);

    // Count how many real appointments overlap with this 30-min window
    const overlappingEvents = events.filter(event => {
        if (!event.start || !event.start.dateTime || !event.end || !event.end.dateTime) return false;

        const eventStart = new Date(event.start.dateTime);
        const eventEnd = new Date(event.end.dateTime);

        // Overlap math: Event starts before slot ends AND event ends after slot starts
        return (eventStart < slotEnd && eventEnd > slotStart);
    });

    // If there are LESS than 2 bookings, we have a barber available!
    if (overlappingEvents.length < 2) {
        // Format the time for the AI to speak (e.g., "10:30 AM")
        const spokenTime = slotStart.toLocaleString('en-US', {
            hour: 'numeric',
            minute: '2-digit',
            hour12: true,
            timeZone: timeZone
        });

        availableSlots.push({
            id: slot.start, // Keep the ISO string for the booking step later
            spoken: spokenTime
        });
    }
});

// 4. Build the spoken summary for Vapi
let spokenSummary = "It looks like we are fully booked for that day.";

if (availableSlots.length > 0) {
    const readable = availableSlots.map(s => s.spoken);
    const topOptions = readable.slice(0, 3); // Cap at 3 so AI doesn't ramble off 15 times

    if (topOptions.length === 1) {
        spokenSummary = `We have ${topOptions[0]} available.`;
    } else if (readable.length <= 3) {
        spokenSummary = `We have ${topOptions.slice(0, -1).join(', ')} and ${topOptions[topOptions.length - 1]} available. Which works better for you?`;
    } else {
        spokenSummary = `I have quite a few openings, including ${topOptions.slice(0, -1).join(', ')} and ${topOptions[topOptions.length - 1]}. Do any of those work, or would you prefer a different time?`;
    }
}

// 5. Return exactly what Vapi needs
return {
    results: [
        {
            toolCallId: toolCallId,
            result: JSON.stringify({
                slots: availableSlots,
                spokenSummary: spokenSummary
            })
        }
    ]
};

// 1. Grab your settings from the Edit Fields node
const editFields = $('Edit Fields').first().json;
const cadenceMs = parseInt(editFields.bookingCadenceMinutes) * 60000; // 30 mins in milliseconds

// 2. Grab the specific date Vapi is asking for
const toolCall = $('Webhook').first().json.body.message.toolCalls[0];
let args = toolCall.function.arguments;
if (typeof args === 'string') {
    args = JSON.parse(args);
}
const searchDateStr = args.initialSearchDateTime;
const baseDate = searchDateStr.split('T')[0]; // "2026-03-03"
const tzOffset = "-06:00"; // Hardcoded to your America/Chicago timezone

// 3. Set the start and end times for the loop
const startHourStr = editFields.workdayStartHour.toString().padStart(2, '0');
const endHourStr = editFields.workdayEndHour.toString().padStart(2, '0');

let currentSlot = new Date(`${baseDate}T${startHourStr}:00:00${tzOffset}`);
const endOfWorkday = new Date(`${baseDate}T${endHourStr}:00:00${tzOffset}`);

// 4. Generate the perfect blank schedule
let potentialSlots = [];

while (currentSlot.getTime() < endOfWorkday.getTime()) {
  const slotEnd = new Date(currentSlot.getTime() + cadenceMs);

  potentialSlots.push({
    start: currentSlot.toISOString(),
    end: slotEnd.toISOString(),
  });

  currentSlot = slotEnd; // Move forward 30 minutes
}

// 5. Pass the blank slots AND the real calendar events to the next node
const inputData = $input.first().json;
let realEvents = [];

// Safely grab the events that came from your 'Aggregate' node
if (inputData && inputData.events) {
    realEvents = inputData.events;
}

return [{
  json: {
    potentialSlots: potentialSlots,
    events: realEvents
  }
}];

// 1. Get the Vapi Tool Call info so we can reply to the right request
const webhookData = $('Webhook').first().json;
const toolCall = webhookData.body.message.toolCalls[0];

// 2. Safely get the events from the Google Calendar node
// (This filters out the empty {} n8n outputs when the slot is completely free)
const items = $input.all().map(item => item.json);
const validEvents = items.filter(e => e.start?.dateTime && e.end?.dateTime);

// 3. Apply your specific Barbershop Rule (Max 2 bookings per slot)
let aiMessage = "";

if (validEvents.length < 2) {
    aiMessage = "Success. This specific time slot is available. You can proceed to ask the user for their name and phone number to book the appointment.";
} else {
    aiMessage = "Failed. This specific time slot already has 2 appointments and is fully booked. Please tell the user it is unavailable and suggest a different time.";
}

// 4. Return the exact JSON structure Vapi needs
return [{
    json: {
        results: [
            {
                toolCallId: toolCall.id,
                result: aiMessage
            }
        ]
    }
}];

